/* ─── App-level event log (visible in Debug tab) ─── */
const _logListeners = [];
const _logEntries = [];
function appLog(msg) {
  const entry = `${new Date().toLocaleTimeString()} — ${msg}`;
  _logEntries.unshift(entry);
  if (_logEntries.length > 50) _logEntries.pop();
  _logListeners.forEach(fn => fn([..._logEntries]));
}
function useAppLog() {
  const [log, setLog] = React.useState([..._logEntries]);
  React.useEffect(() => {
    _logListeners.push(setLog);
    return () => { const i = _logListeners.indexOf(setLog); if(i>-1) _logListeners.splice(i,1); };
  }, []);
  return log;
}

