/* ─── Storage — uses window.storage (artifact persistent storage) ─── */
const store = {
  async get(k) {
    try {
      const result = await window.storage.get(k);
      if (!result) return null;
      try { return JSON.parse(result.value); } catch { return result.value; }
    } catch(e) { return null; }
  },
  async set(k, v) {
    try {
      await window.storage.set(k, JSON.stringify(v));
    } catch(e) {
      console.error(`[store.set] ${k} FAILED:`, e.message);
    }
  },
  async del(k) {
    try { await window.storage.delete(k); } catch {}
  },
  async listKeys(prefix) {
    try {
      const result = await window.storage.list(prefix);
      return result ? result.keys : [];
    } catch { return []; }
  },
};

