function normalizeIngredientLookupName(name) {
  return (name || "").toLowerCase().trim().replace(/[✨🌟]/g, "").replace(/\s+/g, " ").trim();
}

/** Match ingredient names to ABV/sugar tables using exact or whole-phrase matches only. */
function lookupInReferenceTable(name, table) {
  const lower = normalizeIngredientLookupName(name);
  if (!lower) return null;
  if (Object.prototype.hasOwnProperty.call(table, lower)) return table[lower];

  const keys = Object.keys(table).sort((a, b) => b.length - a.length);
  for (const key of keys) {
    const escaped = key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const re = new RegExp(`(?:^|[^a-z0-9])${escaped}(?:[^a-z0-9]|$)`, "i");
    if (re.test(lower)) return table[key];
  }
  return null;
}

function lookupABV(name) {
  const abv = lookupInReferenceTable(name, ABV_TABLE);
  return abv === null ? null : abv;
}

function lookupSugar(name) {
  const sugar = lookupInReferenceTable(name, SUGAR_TABLE);
  return sugar === null ? null : sugar;
}

function calcABV(ingredients) {
  if (!ingredients || !ingredients.length) return null;
  let totalMl = 0, alcoholMl = 0, sugarG = 0, unknown = [];
  const OZ_TO_ML = 29.5735;
  for (const ing of ingredients) {
    if (!ing.name || !ing.amount) continue;
    const unit = (ing.unit || "oz").toLowerCase();
    let ml = 0;
    const amt = parseFloat(ing.amount);
    if (isNaN(amt) || amt <= 0) continue;
    if (unit === "oz")     ml = amt * OZ_TO_ML;
    else if (unit === "ml")    ml = amt;
    else if (unit === "tsp")   ml = amt * 4.92892;
    else if (unit === "tbsp")  ml = amt * 14.7868;
    else if (unit === "cup")   ml = amt * 236.588;
    else if (unit === "dash")  ml = amt * 0.6;
    else if (unit === "drop")  ml = amt * 0.05;
    else if (unit === "splash") ml = amt * 10;
    else continue;
    const abv = lookupABV(ing.name);
    if (abv === null) { unknown.push(ing.name); continue; }
    const sugar = lookupSugar(ing.name) || 0;
    totalMl += ml;
    alcoholMl += ml * (abv / 100);
    sugarG += ml * sugar;
  }
  if (totalMl === 0) return null;
  const dilutedMl = totalMl * 1.22;
  const abv = (alcoholMl / dilutedMl) * 100;
  // Calories: alcohol = 7 cal/g (0.789 g/ml), sugar = 4 cal/g
  const alcoholG = alcoholMl * 0.789;
  const calories = Math.round(alcoholG * 7 + sugarG * 4);
  const skinny = calories <= 150;
  return { abv: Math.round(abv * 10) / 10, calories, skinny, unknown };
}

function sortTags(tags, sliders) {
  if (!tags || !tags.length) return tags;
  return [...tags].sort((a, b) => {
    const aVal = sliders[TAG_SLIDER_MAP[a]] || 0;
    const bVal = sliders[TAG_SLIDER_MAP[b]] || 0;
    return bVal - aVal;
  });
}

