  rating:0, obscura:false,
  addedAt:Date.now()-77, imageUrl:"", myPhoto:"",
  sliders:{ boozy:6, sweet:3, sour:5, bitter:0, fruity:3, herbal:1, smoky:0, spicy:0, rich:1 },
