/* ─── Helpers ─── */
const PERISHABLE_KEYWORDS = ["fresh ","juice","mint","basil","thyme","rosemary","cucumber","egg white","egg yolk","heavy cream","whole egg","milk","butter","strawberr","raspberr","blackberr","passion fruit","fresh ginger","ginger root","muddled","sprig","leaf","leaves"];
const SHELF_STABLE_OVERRIDES = ["liqueur","syrup","bitters","tincture","shrub","cordial","vermouth","wine","beer","cider","bottled","extract","schnapps","brandy","spirit","vodka","gin","rum","tequila","mezcal","whiskey","whisky","cognac","armagnac","aperol","campari","amaro","aperitivo","lillet","pisco","fortified","chartreuse","cointreau","triple sec","curacao","falernum","orgeat","grenadine","absinthe","sambuca","grappa","port","sherry","madeira","sake","mead","cynar","fernet","strega"];
function isPerishable(n) {
  const name = (n||"").toLowerCase();
  if (SHELF_STABLE_OVERRIDES.some(k=>name.includes(k))) return false;
  return PERISHABLE_KEYWORDS.some(k=>name.includes(k));
}
function toMl(amount, unit, scale=1) {
  const a = (parseFloat(amount) || 0) * scale;
  const conversions = {
    oz:29.57, tbsp:15, tsp:5, cup:240,
    dash:0.6, drop:0.05, splash:15, pinch:0.3,
    "fl_oz":29.57, ml:1, l:1000,
  };
  const factor = conversions[(unit||"").toLowerCase()] || null;
  if (!factor) return null;
  const ml = a * factor;
  return ml < 10 ? Math.round(ml*10)/10 : Math.round(ml);
}

function toOz(amount, unit, scale=1) {
  const a = (parseFloat(amount) || 0) * scale;
  // Convert ml back to oz for display
  if ((unit||"").toLowerCase() === "ml") {
    const oz = a / 29.57;
    return oz < 0.1 ? Math.round(oz*100)/100 : Math.round(oz*4)/4; // round to nearest 0.25
  }
  return null; // not a metric unit, show as-is
}

function fmtAmt(amount, scale) {
  const n = parseFloat(amount);
  if (isNaN(n)) return amount;
  const val = n * scale;
  const whole = Math.floor(val);
  const frac = val - whole;
  for (const [f,s] of [[3/4,"¾"],[2/3,"⅔"],[1/2,"½"],[1/3,"⅓"],[1/4,"¼"]])
    if (Math.abs(frac-f)<0.05) return whole ? `${whole} ${s}` : s;
  return val % 1 === 0 ? val.toString() : val.toFixed(2).replace(/\.?0+$/,"");
}

function newCocktail() {
  return { id:Date.now().toString(), name:"", baseSpirit:"", glass:"", occasion:"",
    season:"", difficulty:"", serveStyle:"", tags:[], rating:0, addedAt:Date.now(),
    imageUrl:"", sourceUrl:"", sliders:{...DEFAULT_SLIDERS},
    ingredients:[{name:"",amount:"",unit:"oz"}], instructions:"", notes:"", tastingNotes:"", myPhoto:"", lore:"" };
}

/* ─── Cocktail Photo Component ─── */
function CocktailPhoto({ cocktail, size = 120 }) {
  if (cocktail.imageUrl) {
    return (
      <div style={{
        width: size, height: size,
        borderRadius: 8, overflow: "hidden",
        flexShrink: 0,
        background: "#ede9dc",
      }}>
        <img
          src={cocktail.imageUrl}
          alt={cocktail.name}
          style={{ width:"100%", height:"100%", objectFit:"cover" }}
          onError={e => { e.target.style.display="none"; e.target.nextSibling.style.display="flex"; }}
        />
        <div style={{display:"none",width:"100%",height:"100%",alignItems:"center",justifyContent:"center",color:"#9c9080",fontSize:11}}>
          Photo unavailable
        </div>
      </div>
    );
  }
  const serve = (cocktail.serveStyle||"").toLowerCase();
  const emoji = serve.includes("frozen") ? "🍹"
    : serve.includes("high") ? "🥤"
    : serve.includes("neat") ? "🥃"
    : serve.includes("rock") ? "🥃"
    : "🍸";
  return (
    <div style={{
      width: size, height: size,
      borderRadius: 8, background:"#f7f4ec",
      display:"flex", flexDirection:"column",
      alignItems:"center", justifyContent:"center",
      gap:6, color:"#9c9080", flexShrink:0,
      border:"1px dashed #ddd8c8",
    }}>
      <span style={{fontSize: size * 0.32}}>{emoji}</span>
      <span style={{fontSize: 10, letterSpacing:".04em"}}>Add photo</span>
    </div>
  );
}

